declare(strict_types=1);require dirname(__DIR__).'/vendor/autoload.php';spl_autoload_register(static function(string$c):void{$p='ImAuthenticator\\';if(!str_starts_with($c,$p))return;$f=dirname(__DIR__).'/src/'.str_replace('\\','/',substr($c,strlen($p))).'.php';if(is_file($f))require$f;});use ImAuthenticator\ApplicationAccessService;use ImAuthenticator\AuditLog;use ImAuthenticator\ConditionalAccessService;use ImAuthenticator\Database;use ImAuthenticator\IntegrationToolkitService;use ImAuthenticator\Security;function okTool(bool$c,string$m):void{if(!$c){fwrite(STDERR,"FAIL: {$m}\n");exit(1);}fwrite(STDOUT,"OK: {$m}\n");}$env=static fn(string$n,string$d)=>(getenv($n)===false?$d:(string)getenv($n));$db=new Database(['dsn'=>$env('TEST_DB_DSN','mysql:host=127.0.0.1;dbname=imauth_ci;charset=utf8mb4'),'user'=>$env('TEST_DB_USER','root'),'pass'=>$env('TEST_DB_PASS','')]);$audit=new AuditLog($db);$access=new ApplicationAccessService($db,$audit);$conditional=new ConditionalAccessService($db,$access);$tool=new IntegrationToolkitService($db,['issuer'=>'https://auth.example.test'],$access,$conditional);$s=bin2hex(random_bytes(4));$h=password_hash('toolkit-pass',PASSWORD_ARGON2ID);$db->execute("INSERT INTO users(uuid,name,username,email,password_hash,enabled,lifecycle_status) VALUES(?,?,?,?,?,1,'active')",[Security::uuidV4(),'Toolkit User','tool-'.$s,'tool-'.$s.'@example.test',$h]);$uid=$db->lastInsertId();$db->execute("INSERT INTO applications(uuid,name,slug,url,client_id,client_type,access_policy,enabled) VALUES(?,?,?,?,?,'public','none',1)",[Security::uuidV4(),'Toolkit App','tool-app-'.$s,'https://app.example.test','ima_tool_'.$s]);$aid=$db->lastInsertId();$db->execute('INSERT INTO application_redirect_uris(application_id,redirect_uri) VALUES(?,?)',[$aid,'https://app.example.test/callback']);$access->grantUser($aid,$uid,null);$r=$tool->testUser($aid,$uid,['auth_level'=>1,'risk_score'=>0,'ip'=>'198.51.100.1']);okTool($r['entitled']===true,'Test User evaluates effective entitlement');okTool(($r['conditional_access']['allowed']??false)===true,'Test User evaluates Conditional Access');$app=$db->one('SELECT * FROM applications WHERE id=?',[$aid]);$svg=$tool->qrSvg($app);okTool(str_contains($svg,'<svg')&&strlen($svg)>500,'QR configuration is generated locally as SVG');$payload=$tool->configurationPayload($app);okTool(!array_key_exists('client_secret',$payload),'QR/config payload never includes client secret');fwrite(STDOUT,"Integration toolkit smoke test passed.\n");
